INSERT INTO permissions(permission_code,domain_code,action_code,sensitivity,is_active) SELECT x.c,'dispatch',x.a,x.s,1 FROM (SELECT 'SHIPMENT_MANAGE' c,'manage' a,'sensitive' s UNION ALL SELECT 'TRIP_DISPATCH','dispatch','sensitive' UNION ALL SELECT 'TRIP_STATUS_OPERATIONS','status_operations','sensitive' UNION ALL SELECT 'TRIP_VIEW_OPERATIONS','view_operations','sensitive' UNION ALL SELECT 'TRIP_VIEW_DRIVER','view_driver','normal' UNION ALL SELECT 'TRIP_STATUS_DRIVER','status_driver','normal' UNION ALL SELECT 'SHIPMENT_VIEW_SHIPPER','view_shipper','normal' UNION ALL SELECT 'TRIP_VIEW_CARRIER','view_carrier','normal')x WHERE NOT EXISTS(SELECT 1 FROM permissions p WHERE p.permission_code=x.c);
INSERT INTO role_permissions(role_id,permission_id,scope_class,effective_from,status) SELECT r.role_id,p.permission_id,'global',UTC_TIMESTAMP(6),'active' FROM roles r JOIN permissions p ON p.permission_code IN('SHIPMENT_MANAGE','TRIP_DISPATCH','TRIP_STATUS_OPERATIONS','TRIP_VIEW_OPERATIONS') WHERE r.role_code='MCCOLLIN_OPERATIONS' AND NOT EXISTS(SELECT 1 FROM role_permissions rp WHERE rp.role_id=r.role_id AND rp.permission_id=p.permission_id AND rp.status='active');
INSERT INTO role_permissions(role_id,permission_id,scope_class,effective_from,status) SELECT r.role_id,p.permission_id,'owner',UTC_TIMESTAMP(6),'active' FROM roles r JOIN permissions p ON (r.role_code='DRIVER' AND p.permission_code IN('TRIP_VIEW_DRIVER','TRIP_STATUS_DRIVER')) OR (r.role_code='SHIPPER' AND p.permission_code='SHIPMENT_VIEW_SHIPPER') OR (r.role_code='TRUCK_OWNER' AND p.permission_code='TRIP_VIEW_CARRIER') WHERE NOT EXISTS(SELECT 1 FROM role_permissions rp WHERE rp.role_id=r.role_id AND rp.permission_id=p.permission_id AND rp.status='active');COMMIT;
